  const parseResult = paramSchema.safeParse(req.params);
  if (!parseResult.success) {
    return res.status(400).json({ error: 'Invalid dossierId format' });
  }
  req.validParams = parseResult.data;
  next();
};

app.get('/api/legal/discovery/:dossierId/export', validateDossierParam, async (req, res) => {
  // Streams confidential legal discovery archive by validated dossierId
  const { dossierId } = req.validParams;

  const metadata = await LegalDiscoveryStore.findDossier(dossierId);
  if (!metadata) {
    return res.status(404).json({ error: 'Discovery dossier not found' });
  }

  res.json({
    dossierId,
    caseMatter: metadata.caseMatter,
    privilegedDocuments: metadata.privilegedDocuments,
    exhibits: metadata.exhibits
  });
});

app.listen(7007);

