const express = require('express');
const { z } = require('zod');
const { LegalDiscoveryStore, MatterAccessControl } = require('../services/discoveryStore');

const app = express();

const paramSchema = z.object({
  dossierId: z.string().regex(/^DOS-[A-Z0-9]{8}$/)
});

const validateDossierParam = (req, res, next) => {
  const parseResult = paramSchema.safeParse(req.params);
  if (!parseResult.success) {
    return res.status(400).json({ error: 'Invalid dossierId format' });
  }
  req.validParams = parseResult.data;
  next();
};

app.get('/api/legal/discovery/:dossierId/export', validateDossierParam, async (req, res) => {
  if (!req.user || !req.user.lawFirmId) {
    return res.status(401).json({ error: 'Legal authentication required' });
  }

  const { dossierId } = req.validParams;

  // Verify that the caller's law firm has retained access to this discovery dossier
  const hasAccess = await MatterAccessControl.canAccessDossier(req.user.lawFirmId, dossierId);
  if (!hasAccess) {
    return res.status(403).json({ error: 'Access denied: law firm not retained on this litigation matter' });
  }

  const metadata = await LegalDiscoveryStore.findDossier(dossierId);
  if (!metadata) {
    return res.status(404).json({ error: 'Discovery dossier not found' });
  }

  res.json({
    dossierId,
    caseMatter: metadata.caseMatter,
    privilegedDocuments: metadata.privilegedDocuments,
    exhibits: metadata.exhibits
  });
});

app.listen(7007);
